// web/e2e/player-states.ts - navigation only
export async function gotoLongScore(page: Page): Promise<void> {
  await page.goto('/play');
  await page.getByTestId('open-file-input').setInputFiles('e2e/fixtures/Punk.gp');
}

// `stallMs` is the whole difference between the lanes: Infinity for the pixel shot (the state must
// hold across two samples), 5000 for the accessibility case. Do NOT pass Infinity to setTimeout -
// setTimeout(fn, Infinity) fires immediately.
export async function gotoStalledEngine(page: Page, stallMs: number): Promise<void> {
  await page.route('**/alphatab/esm/alphaTab.mjs', async (route) => {
    if (stallMs === Number.POSITIVE_INFINITY) return; // never settles, never continues
    await new Promise((resolve) => setTimeout(resolve, stallMs));
    await route.continue();
  });
  await page.goto('/play');
}

